import { writeFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { defineConfig } from 'vite'
import vue from '@vitejs/plugin-vue'
import { nuxtComponents, nuxtComposables, vueLibEntries } from './vue-entries.ts'

const root = import.meta.dirname

// `src/vue/<Name>.ts` is generated by `bun run generate:vue-entries` (part of `build`).
const entry = {
  index: resolve(root, 'src/index.ts'),
  ...Object.fromEntries(
    Object.keys(vueLibEntries).map(name => [name, resolve(root, `src/vue/${name}.ts`)]),
  ),
}

const styledSystem = /^styled-system\/(.+)$/

export default defineConfig(({ command }) => ({
  plugins: [
    vue(),
    {
      name: 'fyrst-nuxt-entries',
      closeBundle() {
        writeFileSync(
          resolve(root, 'dist/nuxt-entries.json'),
          `${JSON.stringify({ components: nuxtComponents, composables: nuxtComposables }, null, 2)}\n`,
        )
      },
    },
  ],
  build: {
    // Lib ESM must keep identifiers. Vite 8 Oxc minify emits `var h = defineComponent(...)`,
    // which collides with Nuxt unimport's `import { h } from 'vue'` on linked installs.
    minify: false,
    lib: {
      entry,
      name: 'fyrst-ui',
      cssFileName: 'ui-components',
      formats: ['es', 'cjs'],
      fileName: (format, entryName) => {
        const ext = format === 'es' ? 'js' : 'cjs'
        return entryName === 'index' ? `index.${ext}` : `vue/${entryName}.${ext}`
      },
    },
    rolldownOptions: {
      external: [
        'vue',
        '@pandacss/dev',
        'reka-ui',
        styledSystem,
        /^@fyrst\/ui\/(?:css|helpers|tokens|patterns|types)(?:\/|$)/,
      ],
      output: {
        exports: 'named',
        // Published code imports the runtime `panda lib` ships with the package
        // (`@fyrst/ui/css`, …), not the local codegen folder.
        paths: id => id.replace(styledSystem, '@fyrst/ui/$1'),
      },
    },
    cssCodeSplit: false,
  },
  resolve: {
    alias: {
      '@': resolve(root, 'src'),
      ...(command === 'serve'
        ? { 'styled-system': resolve(root, 'styled-system') }
        : {}),
    },
  },
}))
